import {uid,dayOf,ensureDay,addDays,weekStart,effectiveDate} from './core.js';
import {photosOf,weeklySummary} from './moments.js';

export function createFeatures(api){
 const {esc,btn,icon,textField,actions,showModal,persist,render,toast,prettyDate}=api;
 const modal=()=>document.querySelector('#modal');
 let week=null,uploading=false;
 const sets=()=>api.getData().medSets||[];
 function setsCard(){return `<section class="card"><div class="row between wrap"><h2>Moje zestawy leków</h2>${btn('set-new','Nowy zestaw','text-btn')}</div><p class="small muted">Wybierz zestaw, sprawdź dawki i potwierdź przyjęte leki.</p>${sets().length?`<div class="stack">${sets().map(s=>`<div class="row between wrap"><button type="button" class="secondary" data-action="set-use" data-id="${esc(s.id)}">${esc(s.name)} <span class="small">· ${s.items.length}</span></button><div class="row">${btn('set-edit',icon('edit'),'icon-btn',`data-id="${esc(s.id)}" aria-label="Edytuj zestaw ${esc(s.name)}"`)}${btn('set-delete',icon('close'),'icon-btn',`data-id="${esc(s.id)}" aria-label="Usuń zestaw ${esc(s.name)}"`)}</div></div>`).join('')}</div>`:'<p class="small muted">Na przykład „Poranek” albo „Wieczór”. Zestaw zapisuje wyłącznie Twoje wybory.</p>'}</section>`;}
 function editSet(id){
  const data=api.getData(),old=sets().find(s=>s.id===id),chosen=new Map((old?.items||[]).map(x=>[x.ref,x.dose]));
  const meds=[...data.meds];for(const item of old?.items||[])if(!meds.some(m=>m.id===item.ref))meds.push({id:item.ref,name:item.name+' (usunięty z listy)',missing:true});
  showModal(old?'Edytuj zestaw leków':'Nowy zestaw leków',textField('Nazwa zestawu','set-name',old?.name||'','np. Poranek','text','required maxlength="200"')+`<p class="small muted">Zaznacz leki i wpisz dawki, które chcesz mieć przygotowane. Możesz je zmienić przed każdym zapisem.</p>${meds.length?meds.map(m=>`<div class="batch-detail"><label class="review-check"><input type="checkbox" name="set-med" value="${esc(m.id)}" ${chosen.has(m.id)?'checked':''}><span>${esc(m.name)}</span></label>${textField('Dawka: '+esc(m.name),'set-dose-'+m.id,chosen.get(m.id)??m.dose??'','Opcjonalnie','text','maxlength="200"')}</div>`).join(''):'<p>Najpierw dodaj leki w Ustawieniach lub w formularzu „Lek / suplement”.</p>'}`+actions(),async fd=>{
   const name=fd.get('set-name').trim(),refs=fd.getAll('set-med');if(!name||!refs.length)throw Error('Podaj nazwę i wybierz przynajmniej jeden lek.');
   if(refs.some(ref=>!data.meds.some(m=>m.id===ref)))throw Error('Odznacz leki usunięte z listy lub dodaj je ponownie w Ustawieniach.');
   const next={id:old?.id||uid(),name,items:refs.map(ref=>({ref,name:data.meds.find(m=>m.id===ref).name,dose:fd.get('set-dose-'+ref).trim()}))};
   data.medSets=old?sets().map(s=>s.id===old.id?next:s):[...sets(),next];await persist();modal().close();render();toast('Zapisano zestaw leków');
  });
 }
 function photoEditor(j){return `<div class="journal-photos">${photosOf(j).map(p=>`<figure><button type="button" class="photo-preview" data-action="memory-open" data-date="${api.getDate()}" data-photo="${esc(p.id)}"><img class="photo" src="${p.src}" alt="${esc(p.caption||'Zdjęcie z dziennika')}" loading="lazy"></button><label class="field"><span>Podpis zdjęcia</span><textarea data-photo-caption="${esc(p.id)}" maxlength="1000" placeholder="Co chcesz zapamiętać?">${esc(p.caption)}</textarea></label>${btn('photo-remove','Usuń to zdjęcie','text-btn danger',`data-id="${esc(p.id)}"`)}</figure>`).join('')}</div><label class="photo-pick">${icon('camera')}<p>Dodaj zdjęcia</p><span class="small muted">Możesz wybrać kilka naraz · do 20 zdjęć dziennie</span><input type="file" id="day-photo" accept="image/*" multiple ${uploading?'disabled':''}></label><p class="small muted" id="photo-progress" role="status">${uploading?'Przygotowuję zdjęcia…':''}</p>`;}
 async function addPhotos(files){
  if(uploading)return;const batch=Array.from(files||[]);if(!batch.length)return;
  const data=api.getData(),date=api.getDate();if(photosOf(dayOf(data,date).journal).length+batch.length>20)throw Error('Na jednej kartce mieści się do 20 zdjęć. Wybierz mniej plików.');
  uploading=true;const input=document.querySelector('#day-photo');if(input)input.disabled=true;
  try{const converted=[];for(const [i,file] of batch.entries()){
   const progress=document.querySelector('#photo-progress');if(progress)progress.textContent=`Przygotowuję zdjęcie ${i+1} z ${batch.length}…`;
   if(!file.type.startsWith('image/')||file.size>40*1024*1024)throw Error('Wybierz zdjęcia JPG, PNG lub WebP, każde mniejsze niż 40 MB.');
   let image;try{image=await createImageBitmap(file,{imageOrientation:'from-image'});}catch{throw Error('Nie udało się odczytać jednego ze zdjęć. Żadne nowe zdjęcie nie zostało dodane.');}
   const ratio=Math.min(1,1600/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*ratio);canvas.height=Math.round(image.height*ratio);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);image.close();converted.push({id:uid(),src:canvas.toDataURL('image/jpeg',.82),caption:''});
  }
  const journal=ensureDay(data,date).journal;journal.photos=[...photosOf(journal),...converted];delete journal.photo;await persist({date});render();toast(`Dodano zdjęcia: ${converted.length}`);
  }finally{uploading=false;const input=document.querySelector('#day-photo');if(input){input.disabled=false;input.value='';}const p=document.querySelector('#photo-progress');if(p)p.textContent='';}
 }
 function weeklyView(historySwitch){
  week??=weekStart(api.getDate());const s=weeklySummary(api.getData(),week),fmt=n=>n==null?'—':n.toLocaleString('pl',{maximumFractionDigits:1});
  const frequency=(title,items)=>`<section class="card"><h2>${title}</h2>${items.length?items.map(i=>`<p class="row between wrap"><span>${esc(i.name)}</span><strong>${i.days} dni</strong></p>`).join(''):'<p class="muted small">Brak zapisów w tym tygodniu.</p>'}<p class="small muted">Liczba dni z wpisem, bez traktowania pustych dni jako potwierdzonego braku.</p></section>`;
  return `<div class="page-head"><p class="eyebrow">Chwila spojrzenia wstecz</p><h1>Mój tydzień</h1><p class="muted">Co chcesz zabrać ze sobą dalej?</p></div>${historySwitch()}<section class="card"><div class="row between wrap">${btn('week-prev',icon('left'),'icon-btn','aria-label="Poprzedni tydzień"')}<h2>${prettyDate(s.start)} – ${prettyDate(s.end)} ${s.end.slice(0,4)}</h2>${btn('week-next',icon('right'),'icon-btn',`aria-label="Następny tydzień" ${s.end>=effectiveDate()?'disabled':''}`)}</div><div class="row between wrap"><p class="small muted">${s.partial?'Tydzień jeszcze trwa.':'Poniedziałek–niedziela.'} Dni z zapisami: ${s.recorded} / ${s.dates.length}.</p>${btn('week-current','Bieżący tydzień','text-btn')}</div><div class="metric-row">${Object.entries(s.metrics).map(([k,m])=>`<div class="metric"><strong>${fmt(m.value)}<small> / 10</small></strong><span>${{mood:'Nastrój',energy:'Energia',productivity:'Produktywność'}[k]}</span><small>${m.days} dni z pomiarem</small></div>`).join('')}</div><p class="small muted">Średnie z pomiarów w ciągu dnia. Każdy dzień ma taką samą wagę; dni bez pomiaru pomijamy.</p></section><div class="grid week-grid"><section class="card"><h2>Przyjemne chwile</h2>${s.pleasant.length?s.pleasant.map(p=>`<div class="weekly-moment"><button type="button" class="text-btn" data-action="memory-journal" data-date="${p.date}">${prettyDate(p.date)}</button><p class="history-summary">${esc(p.text)}</p></div>`).join(''):'<p class="small muted">Tutaj znajdziesz przyjemne chwile zapisane w Dzienniku.</p>'}</section><section class="card"><h2>Małe kroki</h2>${s.habits.length?s.habits.map(h=>`<p><strong>${esc(h.name)}</strong><br><span class="small">${h.done} / ${h.target} odhaczeń ${h.weekly?'· cel całego tygodnia':s.partial?'· plan do dziś':''}</span></p>`).join(''):'<p class="small muted">Brak zaplanowanych nawyków w tym tygodniu.</p>'}<p class="small muted">Zestawienie według zapisanego harmonogramu. Nieodhaczone wykonania nie są dowodem niewykonania nawyku.</p></section>${frequency('Najczęściej zapisane objawy',s.symptoms)}${frequency('Aktywności i zdarzenia',s.activities)}</div><section class="card"><h2>Zdjęcia tygodnia <span class="small muted">· ${s.photos.length}</span></h2>${s.photos.length?`<div class="photo-album">${s.photos.map(p=>`<button type="button" class="memory-card" data-action="memory-open" data-date="${p.date}" data-photo="${esc(p.id)}"><img src="${p.src}" alt="${esc(p.caption||'Zdjęcie z '+prettyDate(p.date))}" loading="lazy"><span class="memory-caption"><time>${prettyDate(p.date)}</time><span>${esc(p.caption)}</span></span></button>`).join('')}</div>`:'<p class="small muted">Dodaj zdjęcia w Dzienniku, aby zachować te dni.</p>'}</section>`;
 }
 async function handleAction(action,target){
  if(action==='set-new'||action==='set-edit')editSet(target.dataset.id);
  else if(action==='set-use'){const s=sets().find(s=>s.id===target.dataset.id);if(s)api.openBatch('med',null,s.items);}
  else if(action==='set-delete'){const id=target.dataset.id;showModal('Usunąć zestaw?',`<p>Dotychczasowe wpisy leków pozostaną w dzienniku.</p>`+actions('Usuń zestaw'),async()=>{api.getData().medSets=sets().filter(s=>s.id!==id);await persist();modal().close();render();});}
  else if(action==='photo-remove'){const date=api.getDate(),id=target.dataset.id;showModal('Usunąć zdjęcie?',`<p>Z tej kartki zniknie tylko wybrane zdjęcie i jego podpis.</p>`+actions('Usuń zdjęcie'),async()=>{const j=ensureDay(api.getData(),date).journal;j.photos=photosOf(j).filter(p=>p.id!==id);delete j.photo;await persist({date});modal().close();render();});}
  else if(action==='week-prev'||action==='week-next'){week=addDays(week||weekStart(api.getDate()),action==='week-prev'?-7:7);render();}
  else if(action==='week-current'){week=weekStart(effectiveDate());render();}
  else return false;return true;
 }
 document.addEventListener('input',e=>{const id=e.target.dataset.photoCaption;if(!id)return;const date=api.getDate(),j=ensureDay(api.getData(),date).journal;j.photos=photosOf(j);delete j.photo;const p=j.photos.find(p=>p.id===id);if(p){p.caption=e.target.value;persist({date}).catch(()=>{});}});
 return {setsCard,photoEditor,addPhotos,weeklyView,handleAction};
}
